import type { ExtendedColumnMeta, PaginationParams, TableChangeData } from './types';
import type { ColumnDef } from '@tanstack/vue-table';

export { default as DataTable } from './DataTable.vue';
export { default as DataTableToolbar } from './DataTableToolbar.vue';
export { default as DataTableColumnManager } from './DataTableColumnManager.vue';
export { default as DataTablePinnedRow } from './DataTablePinnedRow.vue';
export { default as PaginationClient } from './PaginationClient.vue';
export { default as PaginationServer } from './PaginationServer.vue';

export { default as DataTableHeader } from './DataTableHeader.vue';
export { default as DataTableBody } from './DataTableBody.vue';
export { default as DataTableEmpty } from './DataTableEmpty.vue';

/**
 * Função auxiliar para converter estado da tabela em query params
 */
export function buildTableQueryParams(e: TableChangeData): PaginationParams {
    const params: PaginationParams = {};

    // Paginação
    if (e.pagination) {
        params.page = e.pagination.pageIndex + 1;
        params.per_page = e.pagination.pageSize;
    }

    // Ordenação
    if (e.sorting && e.sorting.length > 0) {
        const sortItem = e.sorting[0];
        const sortDirection = sortItem?.desc ? 'desc' : 'asc';
        params.sort = `${sortItem?.id}:${sortDirection}`;
    }

    return params;
}

/**
 * Helper para criar meta de coluna com type-safety
 */
export function createColumnMeta<TData = unknown>(meta: ExtendedColumnMeta<TData>): ExtendedColumnMeta<TData> {
    return meta;
}

/**
 * Helper para criar definição de coluna com meta tipada
 */
export function createColumn<TData = unknown>(column: ColumnDef<TData>): ColumnDef<TData> {
    return column;
}

import type {
    Table,
    SortingState,
    VisibilityState,
    PaginationState,
    ColumnDef,
    ColumnMeta,
    Updater,
} from '@tanstack/vue-table';

/**
 * Dados de paginação retornados pelo backend
 */
export interface PaginationMeta {
    current_page: number;
    from: number | null;
    last_page: number;
    per_page: number;
    to: number | null;
    total: number;
}

/**
 * Dados de mudança emitidos pelos eventos da tabela
 */
export interface TableChangeData {
    sorting: SortingState;
    visibility: VisibilityState;
    pagination: PaginationState;
}

/**
 * Opção utilizada em filtros com múltiplas seleções
 */
export interface DataTableFacetedOption {
    label: string;
    value: string;
    icon?: unknown;
}

/**
 * Propriedades aceitas pelo componente DataTable
 */
export interface DataTableProps<TData> {
    /** Estado inicial da tabela */
    initialState?: Partial<TableState>;

    /** Colunas da tabela */
    columns: ColumnDef<TData, unknown>[];

    /** Dados a serem exibidos */
    data: TData[];

    /** Metadados de paginação (quando manualPagination = true) */
    meta?: PaginationMeta;

    /** Define se a ordenação será no servidor ou no cliente */
    manualSorting?: boolean;

    /** Estado de carregamento (primeiro carregamento) */
    isLoadingData?: boolean;

    /** Estado de refetch em background */
    isFetchingData?: boolean;

    /** Remove a paginação */
    withoutPagination?: boolean;

    /** Ativa paginação manual (servidor) */
    manualPagination?: boolean;

    /** Estado atual de paginação */
    pagination?: PaginationState;

    /** Total de registros (opcional, usado com paginação manual) */
    totalCount?: number;

    /** Classe CSS condicional por linha */
    rowClassName?: (row: TData) => string;

    /** Habilita clique na linha */
    enableRowClick?: boolean;

    /** Variante visual da tabela */
    variant?: 'default' | 'striped' | 'bordered' | 'minimal';

    /** Classe(s) extras no container */
    containerClass?: string | string[];

    /** Mantém o cabeçalho fixo (sticky) */
    pinHeader?: boolean;

    /** Permite fixar linhas no topo/base */
    enableRowPinning?: boolean;

    /** Permite fixar colunas na esquerda/direita */
    enableColumnPinning?: boolean;

    /** Permite reordenar colunas */
    enableReorder?: boolean;

    /** Quebra de linha de texto dentro das células */
    textWrap?: boolean;

    /** Callback quando a instância da tabela estiver pronta */
    onTableReady?: (table: Table<TData>) => void;
}

export interface EditableCellMeta {
    /** Define se a célula é editável */
    editable?: boolean;
    /** Tipo de input (text, number, money:2, etc.) */
    inputType?: 'text' | 'string' | 'number' | 'money:2' | 'money:4' | 'cep' | 'cpf' | 'cnpj' | 'cpf_cnpj';
    /** Placeholder do input */
    placeholder?: string;
    /** Prefixo (ex: 'R$ ', '$ ', etc) */
    prefix?: string;
    /** Sufixo (ex: ' %', ' kg', etc) */
    suffix?: string;
}

export interface ExtendedColumnMeta<TData> extends ColumnMeta<TData, unknown> {
    columnName?: string;
    cell?: EditableCellMeta;
}

export type DataTableMeta<TData> = {
    onCellCommit?: (payload: { row: TData; columnId: string; value: unknown }) => void;
    editingCell?: { rowId: string; columnId: string } | null;
    setEditingCell?: (cell: { rowId: string; columnId: string } | null) => void;
};

export type DataTableEmits<TData> = {
    /** Quando muda a ordenação da tabela */
    (e: 'sorting-change', v: Updater<SortingState>): void;

    /** Quando muda a visibilidade das colunas */
    (e: 'visibility-change', v: VisibilityState): void;

    /** Quando muda a paginação */
    (e: 'pagination-change', v: PaginationState): void;

    /** Quando há uma mudança geral de estado */
    (
        e: 'table-change',
        v: {
            sorting: SortingState;
            visibility: VisibilityState;
            pagination: PaginationState;
        }
    ): void;

    /** Quando clica na linha */
    (e: 'row-click', v: TData): void;
    /** Quando uma célula é editada e confirmada */
    (e: 'cell-commit', v: { row: TData; columnId: string; value: unknown }): void;
};

export interface PaginationParams {
    page?: number;
    per_page?: number;
    sort?: string;
}

import {
    getCoreRowModel,
    getExpandedRowModel,
    getPaginationRowModel,
    getSortedRowModel,
    useVueTable,
    type SortingState,
    type VisibilityState,
    type PaginationState,
    type RowSelectionState,
    type RowPinningState,
    type ColumnPinningState,
    type ColumnOrderState,
    type Updater,
} from '@tanstack/vue-table';
import { ref, computed } from 'vue';
import { valueUpdater } from '@/lib/utils';
import type { DataTableProps, PaginationMeta, DataTableEmits, DataTableMeta } from './types';

export function useDataTableState<TData>(props: DataTableProps<TData>, emit: DataTableEmits<TData>) {
    const initialPagination: PaginationState = props.pagination ?? {
        pageIndex: 0,
        pageSize: 10,
    };

    const sorting = ref<SortingState>([]);
    const columnVisibility = ref<VisibilityState>({});
    const columnOrder = ref<ColumnOrderState>([]);
    const columnPinning = ref<ColumnPinningState>({ left: [], right: [] });
    const rowSelection = ref<RowSelectionState>({});
    const expanded = ref<Record<string, boolean>>({});
    const pagination = ref<PaginationState>(initialPagination);
    const rowPinning = ref<RowPinningState>({ top: [], bottom: [] });

    const editingCell = ref<{ rowId: string; columnId: string } | null>(null);

    const setEditingCell = (cell: { rowId: string; columnId: string } | null) => {
        editingCell.value = cell;
    };

    const handleCellCommit = (payload: { row: TData; columnId: string; value: unknown }) => {
        const rowData = payload.row as Record<string, unknown>;
        rowData[payload.columnId] = payload.value;

        emit('cell-commit', payload);
    };

    const metaData = computed<PaginationMeta>(() => props.meta ?? ({} as PaginationMeta));

    const tableMeta = computed<DataTableMeta<TData>>(() => ({
        editingCell: editingCell.value,
        setEditingCell,
        onCellCommit: handleCellCommit,
    }));

    const table = useVueTable({
        get data() {
            return props.data;
        },
        get columns() {
            return props.columns;
        },
        get meta() {
            return tableMeta.value;
        },
        getCoreRowModel: getCoreRowModel(),
        manualSorting: props.manualSorting,
        ...(props.manualSorting ? {} : { getSortedRowModel: getSortedRowModel() }),

        getExpandedRowModel: getExpandedRowModel(),
        enableRowPinning: props.enableRowPinning,
        enablePinning: props.enableColumnPinning,
        ...(props.withoutPagination
            ? {}
            : props.manualPagination
              ? {
                    manualPagination: true,
                    pageCount: metaData.value?.last_page || -1,
                }
              : {
                    getPaginationRowModel: getPaginationRowModel(),
                }),
        state: {
            get sorting() {
                return sorting.value;
            },
            get columnVisibility() {
                return columnVisibility.value;
            },
            get rowSelection() {
                return rowSelection.value;
            },
            get expanded() {
                return expanded.value;
            },
            get pagination() {
                return pagination.value;
            },
            get rowPinning() {
                return rowPinning.value;
            },
            get columnPinning() {
                return columnPinning.value;
            },
            get columnOrder() {
                return columnOrder.value;
            },
        },
        onSortingChange: (updater: Updater<SortingState>) => {
            valueUpdater(updater, sorting);
            emit('sorting-change', updater);
            emit('table-change', {
                sorting: sorting.value,
                visibility: columnVisibility.value,
                pagination: pagination.value,
            });
        },
        onColumnVisibilityChange: (updater: Updater<VisibilityState>) => {
            valueUpdater(updater, columnVisibility);
            emit('visibility-change', columnVisibility.value);
            emit('table-change', {
                sorting: sorting.value,
                visibility: columnVisibility.value,
                pagination: pagination.value,
            });
        },
        onRowSelectionChange: (updaterOrValue: Updater<RowSelectionState>) =>
            valueUpdater(updaterOrValue, rowSelection),
        onExpandedChange: (updaterOrValue) => valueUpdater(updaterOrValue, expanded),
        onPaginationChange: props.withoutPagination
            ? undefined
            : (updater: Updater<PaginationState>) => {
                  valueUpdater(updater, pagination);
                  handlePaginationChange(pagination.value);
              },
        onRowPinningChange: (updaterOrValue) => valueUpdater(updaterOrValue, rowPinning),
        onColumnPinningChange: (updater) => valueUpdater(updater, columnPinning),
        onColumnOrderChange: (updater) => valueUpdater(updater, columnOrder),
    });

    const handlePaginationChange = (v: PaginationState) => {
        emit('pagination-change', v);
        emit('table-change', {
            sorting: sorting.value,
            visibility: columnVisibility.value,
            pagination: v,
        });
    };

    return { table, metaData, handlePaginationChange };
}

import { ref } from 'vue';
import type { Table, ColumnPinningPosition, Column } from '@tanstack/vue-table';
import { toast } from 'vue-sonner';
import type { ExtendedColumnMeta } from './types';

export function useColumnReorder<TData>(table: Table<TData>) {
    const draggedColumnId = ref<string | null>(null);
    const dragOverColumnId = ref<string | null>(null);
    const lastAppliedOrder = ref<string>('');

    let dragPreviewEl: HTMLDivElement | null = null;

    const createDragPreview = (label: string): HTMLDivElement => {
        if (dragPreviewEl) {
            dragPreviewEl.remove();
            dragPreviewEl = null;
        }

        const el = document.createElement('div');
        el.className = 'data-table-drag-preview';
        el.setAttribute('data-pin', 'center');

        const iconSpan = document.createElement('span');
        iconSpan.className = 'data-table-drag-preview-icon';

        const labelSpan = document.createElement('span');
        labelSpan.className = 'data-table-drag-preview-label';
        labelSpan.textContent = label;

        el.appendChild(iconSpan);
        el.appendChild(labelSpan);

        document.body.appendChild(el);
        dragPreviewEl = el;

        return el;
    };

    const updateDragPreviewPin = (pinState: ColumnPinningPosition | false): void => {
        if (!dragPreviewEl) return;

        const pin = pinState === 'left' ? 'left' : pinState === 'right' ? 'right' : 'center';
        dragPreviewEl.setAttribute('data-pin', pin);
    };

    const destroyDragPreview = (): void => {
        if (dragPreviewEl) {
            dragPreviewEl.remove();
            dragPreviewEl = null;
        }
    };

    const getColumnMeta = (column: Column<TData, unknown> | undefined): ExtendedColumnMeta<TData> | undefined => {
        if (!column || !column.columnDef.meta) return undefined;
        return column.columnDef.meta as ExtendedColumnMeta<TData>;
    };

    const handleDragStart = (event: DragEvent, columnId: string, label?: string): void => {
        draggedColumnId.value = columnId;
        lastAppliedOrder.value = '';

        const allColumns = table.getAllLeafColumns();
        const column = allColumns.find((col) => col.id === columnId);

        const meta = getColumnMeta(column);
        const headerLabel = label ?? meta?.columnName ?? (column ? String(column.id) : 'Coluna');

        if (event.dataTransfer) {
            event.dataTransfer.effectAllowed = 'move';
            event.dataTransfer.setData('text/plain', columnId);

            const previewEl = createDragPreview(headerLabel);
            const rect = previewEl.getBoundingClientRect();
            event.dataTransfer.setDragImage(previewEl, rect.width / 2, rect.height / 2);
        }
    };

    const handleDragOver = (
        event: DragEvent,
        columnId: string,
        targetPinState: ColumnPinningPosition | false
    ): void => {
        event.preventDefault();

        if (!draggedColumnId.value || draggedColumnId.value === columnId) {
            return;
        }

        updateDragPreviewPin(targetPinState);

        if (dragOverColumnId.value === columnId) {
            return;
        }

        dragOverColumnId.value = columnId;

        const allColumns = table.getAllLeafColumns();
        const draggedColumn = allColumns.find((col) => col.id === draggedColumnId.value);
        const targetColumn = allColumns.find((col) => col.id === columnId);

        if (!draggedColumn || !targetColumn) return;

        let pinnedLeft = allColumns.filter((col) => col.getIsPinned() === 'left').map((col) => col.id);
        let unpinned = allColumns.filter((col) => !col.getIsPinned()).map((col) => col.id);
        let pinnedRight = allColumns.filter((col) => col.getIsPinned() === 'right').map((col) => col.id);

        const draggedCurrentPin = draggedColumn.getIsPinned();

        if (draggedCurrentPin === 'left') {
            pinnedLeft = pinnedLeft.filter((id) => id !== draggedColumnId.value);
        } else if (draggedCurrentPin === 'right') {
            pinnedRight = pinnedRight.filter((id) => id !== draggedColumnId.value);
        } else {
            unpinned = unpinned.filter((id) => id !== draggedColumnId.value);
        }

        if (targetPinState === 'left') {
            const targetIndex = pinnedLeft.indexOf(columnId);
            if (targetIndex !== -1) {
                pinnedLeft.splice(targetIndex, 0, draggedColumnId.value);
            } else {
                pinnedLeft.push(draggedColumnId.value);
            }
        } else if (targetPinState === 'right') {
            const targetIndex = pinnedRight.indexOf(columnId);
            if (targetIndex !== -1) {
                pinnedRight.splice(targetIndex, 0, draggedColumnId.value);
            } else {
                pinnedRight.push(draggedColumnId.value);
            }
        } else {
            const targetIndex = unpinned.indexOf(columnId);
            if (targetIndex !== -1) {
                unpinned.splice(targetIndex, 0, draggedColumnId.value);
            } else {
                unpinned.push(draggedColumnId.value);
            }
        }

        const finalOrder = [...pinnedLeft, ...unpinned, ...pinnedRight];
        const orderKey = finalOrder.join(',');

        if (orderKey === lastAppliedOrder.value) {
            return;
        }

        lastAppliedOrder.value = orderKey;

        table.setColumnPinning({
            left: pinnedLeft,
            right: pinnedRight,
        });

        table.setColumnOrder(finalOrder);
    };

    const handleDrop = (event: DragEvent): void => {
        event.preventDefault();

        if (draggedColumnId.value) {
            toast.success('Coluna reordenada');
        }

        reset();
    };

    const handleDragEnd = (): void => {
        reset();
    };

    const reset = (): void => {
        draggedColumnId.value = null;
        dragOverColumnId.value = null;
        lastAppliedOrder.value = '';
        destroyDragPreview();
    };

    return {
        draggedColumnId,
        dragOverColumnId,
        handleDragStart,
        handleDragOver,
        handleDrop,
        handleDragEnd,
    };
}

import { ref, onMounted, nextTick, onUnmounted } from 'vue';
import type { Table, Column, Header, Cell } from '@tanstack/vue-table';

type ColumnLike<TData> = Column<TData, unknown> | Header<TData, unknown> | Cell<TData, unknown>;

export function useColumnPinning<TData>(table: Table<TData>) {
    const columnWidths = ref<Record<string, number>>({});
    const isCalculating = ref(false);

    const calculateColumnWidths = () => {
        if (isCalculating.value) return; // Evitar cálculos concorrentes

        isCalculating.value = true;

        const tableElement = document.querySelector('.data-table-container table');
        if (!tableElement) {
            isCalculating.value = false;
            return;
        }

        const headerCells = tableElement.querySelectorAll('thead th');
        const widths: Record<string, number> = {};

        headerCells.forEach((cell) => {
            const columnId = cell.getAttribute('data-column-id');
            if (columnId) {
                widths[columnId] = cell.getBoundingClientRect().width;
            }
        });

        columnWidths.value = widths;
        isCalculating.value = false;
    };

    const getPinnedStyle = (columnOrCell: ColumnLike<TData>, isHeader = false) => {
        const column = 'column' in columnOrCell ? columnOrCell.column : columnOrCell;
        const isPinned = column.getIsPinned?.();

        const baseSize =
            'getSize' in columnOrCell && typeof columnOrCell.getSize === 'function'
                ? columnOrCell.getSize()
                : column.getSize();

        const style: Record<string, string | number> = {
            width: `${baseSize}px`,
        };

        if (!isPinned) {
            return style;
        }

        // Usar largura calculada ou fallback
        const columnWidth = columnWidths.value[column.id] || baseSize;

        style.position = 'sticky';
        style.zIndex = isHeader ? 15 : 5;
        style.minWidth = `${columnWidth}px`;
        style.maxWidth = `${columnWidth}px`;
        style.width = `${columnWidth}px`;

        if (isPinned === 'left') {
            const leftColumns = table.getLeftLeafColumns();
            let leftPosition = 0;

            for (const col of leftColumns) {
                if (col.id === column.id) break;
                leftPosition += columnWidths.value[col.id] || col.getSize();
            }

            style.left = `${leftPosition}px`;
        } else if (isPinned === 'right') {
            const rightColumns = table.getRightLeafColumns();
            let rightPosition = 0;

            let found = false;
            for (const col of rightColumns) {
                if (col.id === column.id) {
                    found = true;
                    continue;
                }
                if (found) {
                    rightPosition += columnWidths.value[col.id] || col.getSize();
                }
            }

            style.right = `${rightPosition}px`;
        }

        return style;
    };

    const getHeaderPinnedStyle = (header: Header<TData, unknown>) => {
        const style = getPinnedStyle(header, true);

        if (header.column.columnDef.maxSize) {
            style.maxWidth = `${header.column.columnDef.maxSize}px`;
        }

        return style;
    };

    const getCellPinnedStyle = (cell: Cell<TData, unknown>) => {
        return getPinnedStyle(cell, false);
    };

    // Debounce para resize
    let resizeTimeout: ReturnType<typeof setTimeout>;
    const handleResize = () => {
        clearTimeout(resizeTimeout);
        resizeTimeout = setTimeout(() => {
            calculateColumnWidths();
        }, 150);
    };

    onMounted(() => {
        nextTick(() => {
            calculateColumnWidths();
            window.addEventListener('resize', handleResize);
        });
    });

    onUnmounted(() => {
        window.removeEventListener('resize', handleResize);
        clearTimeout(resizeTimeout);
    });

    return {
        columnWidths,
        calculateColumnWidths,
        getHeaderPinnedStyle,
        getCellPinnedStyle,
    };
}

@import "./datatable.base.css";
@import "./datatable.pinning.css";
@import "./datatable.reorder.css";
@import "./datatable.drag-preview.css";

@layer components {
    /* ===== Variantes ===== */
    .data-table-default {
        --dt-bg: #ffffff;
        --dt-border: rgba(194, 201, 209, 0.51);
        --dt-header-bg: #fafafa;
        --dt-header-text: #00000080;
        --dt-row-hover: #f9f9fa;
        --dt-row-selected: #F8F8F8;
        --dt-row-odd: #ffffff;
        --dt-cell-text: #6E7487;
        --dt-empty-text: #3E4454;
        --dt-radius: 8px;

        /* Header de coluna pinada (claro) */
        --dt-pinned-header-bg: white;
    }

    .dark .data-table-default {
        /* Tema dark */
        --dt-bg: oklch(0.205 0 0); /* --card */
        --dt-border: oklch(1 0 0 / 10%); /* --border */
        --dt-header-bg: oklch(0.1942 0.0025 145.48); /* --popover */
        --dt-header-text: oklch(0.708 0 0); /* --muted-foreground */
        --dt-row-hover: oklch(0.269 0 0); /* --secondary */
        --dt-row-selected: oklch(0.371 0 0); /* --accent */
        --dt-row-odd: oklch(0.205 0 0); /* --card */
        --dt-cell-text: oklch(0.985 0 0); /* --foreground */
        --dt-empty-text: oklch(0.556 0 0); /* --ring */

        /* Header de coluna pinada (dark) */
        --dt-pinned-header-bg: color-mix(in oklab, var(--color-brand-700) 40%, var(--card) 60%);
    }

    .data-table-striped {
        --dt-row-odd: #fafafa;
    }

    .dark .data-table-striped {
        --dt-row-odd: oklch(0.1715 0.0026 145.46); /* --background dark */
    }

    /* ===== Layout geral ===== */

    .cell-text-wrap td {
        @apply whitespace-normal!;
    }

    .cell-text-wrap .data-table-cell {
        white-space: normal !important;
        word-break: break-word;
    }

    .data-table-header.sticky {
        position: sticky;
        top: 0;
        z-index: 10;
    }

    .data-table-container {
        @apply bg-[var(--dt-bg)] border-[var(--dt-border)] font-open relative w-full;
        border-radius: var(--dt-radius);
        overflow: auto;
    }

    .data-table-header {
        @apply bg-[var(--dt-header-bg)] border-b border-b-[var(--dt-border)];
    }

    .data-table-header:hover {
        @apply bg-[var(--dt-header-bg)]!;
    }

    .data-table-header-cell:first-child {
        border-top-left-radius: var(--dt-radius);
    }

    .data-table-header-cell:last-child {
        border-top-right-radius: var(--dt-radius);
    }

    .data-table-header-cell {
        @apply whitespace-nowrap text-sm font-medium transition-all disabled:pointer-events-none disabled:opacity-50 outline-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] hover:text-accent-foreground dark:hover:bg-accent/50 px-6 -ml-3 h-8 hover:bg-transparent!;
        padding: 18px 16px 6px 16px;
        border-right: 1px solid var(--dt-border);
    }

    .data-table-header-cell:last-child {
        border-right: none;
    }

    .data-table-row {
        border-bottom-width: 1px;
        border-bottom-color: var(--dt-border);
        transition-property: background-color;
        transition-duration: 150ms;
        transition-timing-function: ease;
    }

    .data-table-row:last-child .data-table-cell:first-child {
        border-bottom-left-radius: var(--dt-radius);
    }

    .data-table-row:last-child .data-table-cell:last-child {
        border-bottom-right-radius: var(--dt-radius);
    }

    .data-table-row:nth-child(odd) {
        @apply bg-[var(--dt-row-odd)]!;
    }

    .data-table-body .data-table-row:hover {
        @apply bg-[var(--dt-row-hover)]!;
    }

    .data-table-row-selected {
        background-color: var(--dt-row-selected) !important;
    }

    .data-table-row-clickable {
        cursor: pointer;
    }

    .data-table-cell {
        @apply text-[var(--dt-cell-text)]! text-sm font-open;
        border-right: 1px solid var(--dt-border);
    }

    .data-table-cell:last-child {
        border-right: none;
    }

    .data-table-empty {
