        background-color: var(--dt-bg) !important;
    }

    .data-table-striped .data-table-row:nth-child(odd) .data-table-cell-pinned-left,
    .data-table-striped .data-table-row:nth-child(odd) .data-table-cell-pinned-right {
        background-color: var(--dt-row-odd) !important;
    }

    .data-table-body .data-table-row:hover .data-table-cell-pinned-left,
