export type SelectCheckboxProps<TData> = {
    type: 'header' | 'cell';
    table?: Table<TData>;
    row?: Row<TData>;
};

export function createSelectColumn<TData>(): ColumnDef<TData> {
    const SelectCheckboxTyped = SelectCheckbox as unknown as DefineComponent<SelectCheckboxProps<TData>>;
    return {
        id: 'select',
        header: ({ table }) =>
            h(SelectCheckboxTyped, {
                type: 'header',
                table,
            }),
        cell: ({ row }) =>
            h(SelectCheckboxTyped, {
                type: 'cell',
                row,
            }),
        enableSorting: false,
        enableHiding: false,
        size: 40,
        minSize: 40,
        maxSize: 40,
    };
}

export { default as ColumnManagerTrigger } from './ColumnManagerTrigger.vue';
export { default as ColumnManagerHeader } from './ColumnManagerHeader.vue';
export { default as ColumnManagerSearch } from './ColumnManagerSearch.vue';
export { default as ColumnManagerActions } from './ColumnManagerActions.vue';
export { default as ColumnManagerItem } from './ColumnManagerItem.vue';
export { default as ColumnManagerEmpty } from './ColumnManagerEmpty.vue';
